        if good[u]:
            for v in adj[u]:
                if good[v]:
                    eadj[u].append(v)

    visited = [False] * (N + 1)
    parent = [-1] * (N + 1)
    sub = [0] * (N + 1)
    up = [0] * (N + 1)
    best = 0

