                up[c] = 1 + s

        # f(u) = 1 + top 4 of h-values from each neighbor direction (u as alkane root).
        for u in order:
            pu = parent[u]
            vals = []
            if pu != -1:
                vals.append(up[u])
            for v in eadj[u]:
